do $$ begin if not exists(select 1 from pg_constraint where conname='inspection_responses_inspection_item_key') then alter table public.inspection_responses add constraint inspection_responses_inspection_item_key unique(inspection_id,checklist_item_id);end if;end $$;create or replace function public.submit_inspection_checklist(p_inspection_id uuid,p_responses jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid();v_role public.app_role;v_inspection public.inspections%rowtype;v_item jsonb;v_item_id uuid;v_result text;v_note text;v_response_id uuid;v_question text;v_criteria text;v_critical boolean;v_risk public.risk_level;v_required integer;v_supplied integer;v_non_compliant integer:=0;v_created_findings integer:=0;begin if v_uid is null then raise exception 'Sesi login tidak tersedia';end if;select role into v_role from public.profiles where id=v_uid and active=true;if v_role not in('admin','ktt_ptl','inspector') then raise exception 'Anda tidak berwenang mengisi checklist';end if;select * into v_inspection from public.inspections where id=p_inspection_id for update;if not found then raise exception 'Inspeksi tidak ditemukan';end if;if v_role='inspector' and v_inspection.inspector_id<>v_uid then raise exception 'Inspeksi bukan penugasan Anda';end if;if v_inspection.status in('closed','cancelled') then raise exception 'Inspeksi sudah ditutup atau dibatalkan';end if;select count(*) into v_required from public.checklist_items where template_id=v_inspection.template_id;select count(distinct(x->>'checklist_item_id')) into v_supplied from jsonb_array_elements(coalesce(p_responses,'[]'::jsonb))x;if v_required=0 then raise exception 'Template tidak memiliki butir checklist';end if;if v_supplied<>v_required then raise exception 'Semua butir checklist wajib dijawab (% dari %)',v_supplied,v_required;end if;for v_item in select value from jsonb_array_elements(p_responses)loop v_item_id:=(v_item->>'checklist_item_id')::uuid;v_result:=v_item->>'result';v_note:=nullif(trim(v_item->>'note'),'');if v_result not in('compliant','non_compliant','na')then raise exception 'Hasil checklist tidak valid';end if;select question,acceptance_criteria,critical into v_question,v_criteria,v_critical from public.checklist_items where id=v_item_id and template_id=v_inspection.template_id;if not found then raise exception 'Butir checklist tidak sesuai template';end if;if v_result='non_compliant' and v_note is null then raise exception 'Catatan wajib untuk hasil Tidak Sesuai';end if;insert into public.inspection_responses(inspection_id,checklist_item_id,result,note,answered_by,answered_at)values(p_inspection_id,v_item_id,v_result,v_note,v_uid,now())on conflict(inspection_id,checklist_item_id)do update set result=excluded.result,note=excluded.note,answered_by=excluded.answered_by,answered_at=now()returning id into v_response_id;if v_result='non_compliant' then v_non_compliant:=v_non_compliant+1;if not exists(select 1 from public.findings where response_id=v_response_id)then v_risk:=case when v_critical then 'extreme'::public.risk_level else v_inspection.risk_level end;insert into public.findings(finding_no,inspection_id,response_id,title,description,finding_type,risk_level,pic_id,verifier_id,target_close_at,status,created_by)values('FND-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),p_inspection_id,v_response_id,v_question,coalesce(v_note,'Tidak sesuai')||case when v_criteria is not null then E'\nKriteria: '||v_criteria else '' end,'system_gap',v_risk,v_uid,v_uid,now()+case v_risk when 'extreme' then interval '1 day' when 'high' then interval '3 days' when 'medium' then interval '7 days' else interval '14 days' end,'open',v_uid);v_created_findings:=v_created_findings+1;end if;end if;end loop;update public.inspections set status=case when v_non_compliant>0 then 'follow_up'::public.inspection_status else 'submitted'::public.inspection_status end,started_at=coalesce(started_at,now()),submitted_at=now(),updated_at=now()where id=p_inspection_id;insert into public.audit_logs(entity_type,entity_id,action,new_data,actor_id)values('inspection',p_inspection_id,'checklist_submitted',jsonb_build_object('responses',v_required,'non_compliant',v_non_compliant,'findings_created',v_created_findings),v_uid);return jsonb_build_object('responses_saved',v_required,'non_compliant',v_non_compliant,'findings_created',v_created_findings);end;$$;revoke all on function public.submit_inspection_checklist(uuid,jsonb)from public;grant execute on function public.submit_inspection_checklist(uuid,jsonb)to authenticated;